for name,path in [('DV','/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'),('DVB','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,path))
C=colors.HexColor
NAVY=C('#14314B');TURQ=C('#117D87');ORANGE=C('#CD6748');GRAY=C('#536374');WHITE=colors.white
styles={}
styles['title']=ParagraphStyle('Title',fontName='DVB',fontSize=24,leading=29,textColor=NAVY,spaceAfter=12)
styles['subtitle']=ParagraphStyle('Subtitle',fontName='DV',fontSize=13,leading=18,textColor=TURQ,spaceAfter=16)
styles['h1']=ParagraphStyle('H1',fontName='DVB',fontSize=14.5,leading=19,textColor=NAVY,spaceBefore=12,spaceAfter=8,keepWithNext=True)
styles['h2']=ParagraphStyle('H2',fontName='DVB',fontSize=10.8,leading=15,textColor=TURQ,spaceBefore=10,spaceAfter=6,keepWithNext=True)
styles['p']=ParagraphStyle('P',fontName='DV',fontSize=9.1,leading=15,textColor=C('#223648'),spaceAfter=8)
styles['small']=ParagraphStyle('Small',fontName='DV',fontSize=7.6,leading=11.2,textColor=GRAY,spaceAfter=6)
