def P(text,sty='p'):return Paragraph(text,styles[sty])
def heading(t): story.append(P(t,'h1'))
def sub(t): story.append(P(t,'h2'))
def para(t): story.append(P(t))
def table(items,widths=None):
  processed=[]
  for i,row in enumerate(items): processed.append([P(str(v),'label' if i==0 else 'small') for v in row])
  t=Table(processed,colWidths=widths,hAlign='LEFT',repeatRows=1)
  t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),C('#E3F0EF')),('GRID',(0,0),(-1,-1),.35,C('#D7E3E9')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
  story.append(t);story.append(Spacer(1,10))
def image(path,width=170*mm):
 from PIL import Image as PIL
 p=Path(path);im=PIL.open(p);return Image(str(p),width=width,height=width*im.height/im.width)
def figure(figid,cap):
 story.append(image(ROOT/'figures'/f'{figid}.png',130*mm));story.append(P(cap,'fig'))
def new():story.append(PageBreak())
def footer(canvas,doc):
 canvas.saveState();width,height=A4
 canvas.setStrokeColor(C('#D8E4E7'));canvas.line(21*mm,19*mm,width-21*mm,19*mm)
 canvas.setFont('DV',7);canvas.setFillColor(GRAY)
 canvas.drawString(21*mm,14.2*mm,'paceval.  |  Industrial Research  |  Distillation VLE Kernels')
 canvas.drawRightString(width-21*mm,14.2*mm,f'14 November 2026   •   {doc.page}')
 canvas.restoreState()

